def drive(me, enemy, arena):
    if not me.can_drive:
        return (0.0, 0.0)
    ex = enemy.x - me.x
    ey = enemy.y - me.y
    r = sqrt(me.x * me.x + me.y * me.y)
    tx = ex
    ty = ey
    if r > 4.2:
        k = (r - 4.2) / 1.3
        if k > 1.0:
            k = 1.0
        tx = ex * (1.0 - k) - me.x * k
        ty = ey * (1.0 - k) - me.y * k
    th = degrees(atan2(ty, tx))
    err = th - me.heading
    if err > 180.0:
        err = err - 360.0
    if err < -180.0:
        err = err + 360.0
    if err > 6.0:
        s = 1.0
    elif err < -6.0:
        s = -1.0
    else:
        s = 0.0
    base = 1.0
    if abs(err) > 35.0:
        base = 0.75
    l = base + 0.6 * s
    rr = base - 0.6 * s
    if l > 1.0:
        l = 1.0
    if rr > 1.0:
        rr = 1.0
    if l < -1.0:
        l = -1.0
    if rr < -1.0:
        rr = -1.0
    return (l, rr)


