    try:
        b = bearing_to(enemy.x, enemy.y)
        d = distance_to(enemy.x, enemy.y)
        if me.inverted or me.on_side or not me.can_drive:
            return (0, 0)
        # keep the front (the disc) pointed at the enemy
        if abs(b) > 100 and d > 1.5:
            # enemy behind: back up while turning
            l = max(-1.0, min(1.0, -0.8 - b / 90.0))
            r = max(-1.0, min(1.0, -0.8 + b / 90.0))
            return (l, r)
        l = max(-1.0, min(1.0, 1.0 + b / 60.0))
        r = max(-1.0, min(1.0, 1.0 - b / 60.0))
        # back off briefly if enemy spinner is hot and we are very close and ours is slow
        if d < 0.9 and abs(enemy.weapons.get("front", {}).get("rpm", 0)) > 1000:
            try:
                if me.weapons["front"]["energy_j"] < 5000:
                    return (-0.6, -0.6)
            except (KeyError, TypeError):
                pass
        return (l, r)
    except Exception:
        return (0.5, 0.5)

