def drive(me, enemy, arena):
    try:
        if not me.can_drive or me.inverted:
            return (0, 0)
        b = bearing_to(enemy.x, enemy.y)
        if abs(b) <= 90:
            e = b
            l = max(-1.0, min(1.0, 1.0 + e / 60.0))
            r = max(-1.0, min(1.0, 1.0 - e / 60.0))
        else:
            e = b - 180.0
            if e > 180.0:
                e -= 360.0
            if e < -180.0:
                e += 360.0
            l = max(-1.0, min(1.0, -1.0 + e / 90.0))
            r = max(-1.0, min(1.0, -1.0 - e / 90.0))
        return (l, r)
    except Exception:
        return (0, 0)

